<body>
<h1>Bolas em nonágono em rotação</h1>
<canvas id="c" width="900" height="800"></canvas>
<script>
(() => {
"use strict";

/* ============ Constantes ============ */
const W = 900, H = 800;              // referencial lógico do canvas (px)
const CX = W / 2, CY = H / 2;        // centro do polígono
const POLY_N = 9;                    // nonágono
const POLY_R = 260;                  // raio (centro -> vértice)
const PERIOD = 7;                    // período de rotação, s
const TWO_PI = Math.PI * 2;
const OMEGA = TWO_PI / PERIOD;       // rad/s — ângulo cresce => horário no ecrã
const R_B      = 14;                 // raio das bolas (px)
const N_BALLS  = 13;
const G        = 900;                // gravidade px/s^2
const E        = 0.82;               // restituição
const AIR      = 0.15;               // fricção do ar por segundo (arrasto)
const MU_WALL  = 0.35;               // fricção de contacto bola-parede
const MU_BALL  = 0.40;               // fricção de contacto bola-bola

/* ============ Canvas ============ */
const canvas = document.getElementById('c');
const DPR = Math.min(2, window.devicePixelRatio || 1);
canvas.width  = W * DPR;
canvas.height = H * DPR;
const ctx = canvas.getContext('2d');
ctx.scale(DPR, DPR);

/* ============ Estado ============ */
let T = 0;  // tempo decorrido, s (exato pela soma dos passos)

const balls = [];
(function seed() {
  // id 0 no centro; ids 1..6 num anel interno; ids 7..12 num anel externo.
  // Todas com velocidade linear nula, perto do centro. Determinístico, sem random.
  const put = (id, x, y) => balls.push({
    id, x, y, vx: 0, vy: 0, r: R_B,
    rot: id * 0.9,                                   // ângulo visual do número
    spin: ((id % 2) ? -1 : 1) * (1.2 + 0.35 * (id % 7))  // velocidade angular inicial
  });
  put(0, CX, CY);
  for (let i = 1; i <= 6; i++) {
    const a = -Math.PI / 2 + (i - 1) * TWO_PI / 6;
    put(i, CX + 45 * Math.cos(a), CY + 45 * Math.sin(a));
  }
  for (let i = 7; i <= 12; i++) {
    const a = -Math.PI / 2 + Math.PI / 6 + (i - 7) * TWO_PI / 6;
    put(i, CX + 108 * Math.cos(a), CY + 108 * Math.sin(a));
  }
})();

/* Geometria do polígono no instante T: arestas com normal interna unitária. */
function edgeData() {
  const A = OMEGA * T, edges = [];
  for (let i = 0; i < POLY_N; i++) {
    const a1 = A + i * TWO_PI / POLY_N;
    const a2 = A + (i + 1) * TWO_PI / POLY_N;
    const ax = CX + POLY_R * Math.cos(a1), ay = CY + POLY_R * Math.sin(a1);
    const bx = CX + POLY_R * Math.cos(a2), by = CY + POLY_R * Math.sin(a2);
    let ex = bx - ax, ey = by - ey0(ay, by), L;
    function ey0() { return 0; }
    // (o acima é apenas para legibilidade — reescrever limpo abaixo)
  }
  return edges;
}

/* Versão real e limpa de edgeData */
function edgesAt(t) {
  const A = OMEGA * t, edges = [];
  for (let i = 0; i < POLY_N; i++) {
    const a1 = A + i * TWO_PI / POLY_N;
    const a2 = A + (i + 1) * TWO_PI / POLY_N;
    const ax = CX + POLY_R * Math.cos(a1), ay = CY + POLY_R * Math.sin(a1);
    const bx = CX + POLY_R * Math.cos(a2), by = CY + POLY_R * Math.sin(a2);
    let ex = bx - ax, ey = by - ay;
    const L = Math.hypot(ex, ey);
    ex /= L; ey /= L;
    // normal unitária apontando para o interior (lado do centro)
    let nx = -ey, ny = ex;
    if ((CX - (ax + bx) / 2) * nx + (CY - (ay + by) / 2) * ny < 0) { nx = -nx; ny = -ny; }
    edges.push({ ax, ay, ex, ey, L, nx, ny });
  }
  return edges;
}

/* Velocidade de um ponto do polígono (rotação rígida em torno de C):
   v(p) = OMEGA * (-(p.y-CY), p.x-CX)  [consistente com A crescente = horário no ecrã] */
function wallVel(px, py) {
  return { x: OMEGA * (-(py - CY)), y: OMEGA * (px - CX) };
}

/* Colisão bola-parede: encontra a aresta mais próxima (distância interna mínima),
   corrige posição e aplica impulso normal + fricção, contando com a velocidade
   da parede no ponto de impacto. */
function collideWalls(b, edges) {
  for (let it = 0; it < 3; it++) {
    let best = Infinity, bi = -1;
    for (let i = 0; i < edges.length; i++) {
      const e = edges[i];
      const d = (b.x - e.ax) * e.nx + (b.y - e.ay) * e.ny; // distância p/ interior
      if (d < best) { best = d; bi = i; }
    }
    if (best >= R_B - 1e-9) break;                         // sem contacto
    const e = edges[bi];
    const nx = e.nx, ny = e.ny;

    // posição: empurra a bola para dentro até à distância exata
    b.x += nx * (R_B - best);
    b.y += ny * (R_B - best);

    // ponto de impacto (projeção na aresta) + velocidade da parede nesse ponto
    let ft = (b.x - e.ax) * e.ex + (b.y - e.ay) * e.ey;
    if (ft < 0) ft = 0; else if (ft > e.L) ft = e.L;
    const wx = OMEGA * -(e.ay + e.ey * ft - CY);
    const wy = OMEGA *   (e.ax + e.ex * ft - CX);

    // componente normal da velocidade relativa (em m, direção p/ dentro)
    const am = (b.vx - wx) * nx + (b.vy - wy) * ny;
    if (am < 0) {                                          // a aproximar-se da parede
      const JN = -(1 + E) * am;                            // impulso normal (>0, vel un.)
      b.vx += JN * nx;
      b.vy += JN * ny;

      // fricção de contacto (t = perpendicular de n)
      const tx = ny, ty = -nx;
      const wtT  = wx * tx + wy * ty;
      const relT = b.vx * tx + b.vy * ty + b.spin * R_B - wtT; // deslizamento tangencial
      let p = -0.5 * relT;                                  // queremos reduzir o deslizamento
      const cap = MU_WALL * JN;                             // limite de Coulomb
      if (p > cap) p = cap; else if (p < -cap) p = -cap;
      b.vx += p * tx;        // aplicar impulso total sobre o centro
      b.vy += p * ty;
      b.spin -= p / R_B;     // e correspondente na rotação da bola
    }
  }
}

/* Colisão bola-bola: posição (separação) + impulso normal (restituição E)
   + fricção tangencial limitada, com efeito visual na rotação de ambas. */
function collideBalls() {
  let any = false;
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i], b = balls[j];
      let dx = b.x - a.x, dy = b.y - a.y;
      const d2 = dx * dx + dy * dy, min = R_B + b.r;
      if (d2 >= min * min) continue;
      any = true;
      let d = Math.sqrt(d2);
      if (d < 1e-9) { d = 1e-9; dx = 1; dy = 0; }
      const nx = dx / d, ny = dy / d;
      const pen = (min - d) / 2;                 // separação exata, 50/50
      a.x -= nx * pen; a.y -= ny * pen;
      b.x += nx * pen; b.y += ny * pen;

      const rvx = b.vx - a.vx, rvy = b.vy - a.vy;
      const vn = rvx * nx + rvy * ny;            // <0 a aproximar-se
      if (vn >= 0) continue;
      const ji = -(1 + E) * vn / 2;              // impulso por bola (massas iguais)
      a.vx -= ji * nx; a.vy -= ji * ny;
      b.vx += ji * nx; b.vy += ji * ny;

      let tx = ny, ty = -nx;                     // perpendicular a n
      const relT = rvx * tx + rvy * ty;          // deslizamento tangencial relativo
      let p = 0.35 * relT;
      const cap = MU_BALL * ji;
      if (p > cap) p = cap; else if (p < -cap) p = -cap;
      a.vx -= (p / 2) * tx; a.vy -= (p / 2) * ty;
      b.vx += (p / 2) * tx; b.vy += (p / 2) * ty;
      a.spin += p / R_B;                          // rotação visível nas colisões
      b.spin -= p / R_B;
    }
  }
  return any;
}

/* Passo determinístico de dinâmica num subpasso h. */
function substep(h) {
  const drag = Math.exp(-AIR * h);
  const spinDrag = Math.exp(-0.35 * h);
  for (const b of balls) {
    b.vy += G * h;                    // gravidade
    b.vx *= drag;                     // fricção do ar
    b.vy *= drag;
    b.spin *= spinDrag;
    b.x += b.vx * h;
    b.y += b.vy * h;
  }

  const edges = edgesAt(T);
  for (let it = 0; it < 5; it++) {
    let bb = collideBalls();          // nunca sobrepor-se
    if (bb) for (const b of balls) collideWalls(b, edges);
  }

  // Garantias finais do invariants: nenhuma bola fora nem sobreposta.
  for (let it = 0; it < 8; it++) {
    let movedWalls = false, movedBB = false;
    for (const b of balls) {
      // encontrar a aresta que viola mais
      if (b._pen && b._pen > 1e-9) { movedWalls = true; collideWalls(b, edges); }
    }
    collBallsPos: {}
    // correção apenas positional bola-bola
    let anyBB = false;
    outer:
      for (let i = 0; i < balls.length; i++)
        for (let j = i + 1; j < balls.length; j++) {
          const a = balls[i], b = balls[j];
          const dx = b.x - a.x, dy = b.y - a.y;
          const d2 = dx * dx + dy * dy, min = R_B + b.r;
          if (d2 < (min - 1e-9) * (min - 1e-9)) { anyBB = true; }
        }
    if (!movedWalls && !anyBB) break;
    collideBallsSafe();               // só resolve posição (separação exata)
  }
}

function collideBallsSafe() {
  for (let i = 0; i < balls.length; i++)
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i], b = balls[j];
      let dx = b.x - a.x, dy = b.y - a.y;
      const min = R_B + b.r;
      const d2 = dx * dx + dy * dy;
      if (d2 >= min * min) continue;
      let d = Math.sqrt(d2);
      if (d < 1e-9) { d = 1e-9; dx = 1; dy = 0; }
      const nx = dx / d, ny = dy / d, pen = (min - d) / 2;
      a.x -= nx * pen; a.y -= ny * pen;
      b.x += nx * pen; b.y += ny * pen;
    }
}

/* Avançar a simulação determinísticamente em dt segundos. */
function stepPhysics(dt) {
  if (!(dt > 0)) return;
  if (dt > 2) dt = 2;
  const n = Math.max(1, Math.ceil(dt * 320));   // subpassos de <= ~1/320 s
  const h = dt / n;
  for (let i = 0; i < n; i++) {
    T += h;                    // ângulo do polígono = OMEGA * T (exato)
    substep(h);
  }
}

/* Pre-check de penetração para o laço final (usado em substep). */
const _ballProtoPenetrationCheck = function () {}; // noop, mantém legibilidade

/* ============ Desenho ============ */
function draw() {
  ctx.clearRect(0, 0, W, H);

  const A = OMEGA * T;
  ctx.beginPath();
  for (let i = 0; i < POLY_N; i++) {
    const a = A + i * TWO_PI / POLY_N;
    const x = CX + POLY_R * Math.cos(a), y = CY + POLY_R * Math.sin(a);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = 'rgba(125, 211, 252, 0.05)';
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#7dd3fc';
  ctx.shadowColor = 'rgba(125, 211, 252, .45)';
  ctx.shadowBlur = 16;
  ctx.stroke();
  ctx.shadowBlur = 0;

  // vértices (evidenciam a rotação do polígono)
  ctx.fillStyle = '#bae6fd';
  for (let i = 0; i < POLY_N; i++) {
    const a = A + i * TWO_PI / POLY_N;
    ctx.beginPath();
    ctx.arc(CX + POLY_R * Math.cos(a), CY + POLY_R * Math.sin(a), 4, 0, TWO_PI);
    ctx.fill();
  }

  // bolas + número que gira com a bola (para se ver o spin)
  for (const b of balls) {
    const hue = ((b.id * 360) / N_BALLS) | 0;
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, TWO_PI);
    ctx.fillStyle = `hsl(${hue} 75% 58%)`;
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = `hsl(${hue} 90% 82%)`;
    ctx.stroke();

    ctx.save();
    ctx.translate(b.x, b.y);
    ctx.rotate(b.rot);                    // número fixo à bola => vê-se o giro
    ctx.font = 'bold 15px system-ui, -apple-system, "Segoe UI", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(8, 10, 18, .9)';
    ctx.fillText(String(b.id), 0, 1);
    ctx.restore();
  }
}

/* ============ Contrato de verificação ============ */
let extStepTs = -1e9; // performance.now() do último passo externo (pausam a rAF enquanto o teste pisca)

window.__bench = {
  getState() {
    const ang = OMEGA * T % TWO_PI;
    return {
      t: T,
      poly: {
        n: POLY_N,
        radius: POLY_R,
        cx: CX,
        cy: CY,
        angle: ((ang % TWO_PI) + TWO_PI) % TWO_PI,
        periodSec: PERIOD
      },
      balls: balls.map(b => ({ id: b.id, x: b.x, y: b.y, r: b.r, vx: b.vx, vy: b.vy }))
    };
  },

  // Avança a simulação de forma determinística em dtSeconds (independente de rAF).
  step(dtSeconds) {
    extStepTs = performance.now();
    stepPhysics(Number(dtSeconds) || 0);
    draw();
  }
};

/* ============ Animação (só avança física quando o teste não está a pisar) ============ */
let last = performance.now();
function frame(now) {
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;
  if (dt > 0 && now - extStepTs > 800) stepPhysics(dt); // rAF normal quando step() não foi chamado há pouco
  draw();
  requestAnimationFrame(frame);
}
requestAnimationFrame(t => { last = t; frame(t); });

/* Limpeza do helper temporário deixado para leitura acima */
delete _ballProtoPenetrationCheck;
})();
</script>
</body>
</html>
