function stepPhysics(dt) {
  if (!(dt > 0)) return;
  if (dt > 2) dt = 2;
  const n = Math.max(1, Math.ceil(dt * 320));   // subpassos de <= ~1/320 s
  const h = dt / n;
  for (let i = 0; i < n; i++) {
    T += h;                    // ângulo do polígono = OMEGA * T (exato)
    substep(h);
  }
}

