edits.newText:
  // Garantia final do invariante: nenhuma bola fora do polígono nem sobreposta
  // (correção apenas positional; projeções cíclicas exatas convergem).
  fixPositions(edges);
}

function fixPositions(edges) {
  for (let it = 0; it < 64; it++) {
    let anyFixed = false;

    // separação bola-bola (exata, metade para cada lado)
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i], b = balls[j];
        let dx = b.x - a.x, dy = b.y - a.y;
        const min = R_B + b.r;
        const d2 = dx * dx + dy * dy;
        if (d2 >= min * min) continue;
        let d = Math.sqrt(d2);
        if (d < 1e-9) { d = 1e-9; dx = 1; dy = 0; }
        const nx = dx / d, ny = dy / d, pen = min - d;
        a.x -= nx * pen / 2; a.y -= ny * pen / 2;
        b.x += nx * pen / 2; b.y += ny * pen / 2;
        anyFixed = true;
      }
    }

    // projeão cíclica de cada bola em todas as meias-rectas (arestas)
    for (const b of balls) {
      for (let i = 0; i < edges.length; i++) {
        const e = edges[i];
        const d = (b.x - e.ax) * e.nx + (b.y - e.ay) * e.ny;
        if (d > R_B - 1e-9) continue;
        b.x += e.nx * (R_B - d);
        b.y += e.ny * (R_B - d);
        anyFixed = true;
      }
    }

    if (!anyFixed) return; // tudo dentro dos limites — convergiu
  }
}

edits.oldText:
