}

function fixOnlyPass(edges) {
  let fixed = false;
  for (const b of balls) {
    // aresta mais próxima: distância interna mínima
    let best = Infinity, bi = -1;
    for (let i = 0; i < edges.length; i++) {
      const e = edges[i];
      const d = (b.x - e.ax) * e.nx + (b.y - e.ay) * e.ny;
      if (d < best) { best = d; bi = i; }
    }
    if (best > R_B - 1e-9) continue;
    const e = edges[bi];
    b.x += e.nx * (R_B - best);
    b.y += e.ny * (R_B - best);
    fixed = true;
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i], b = balls[j];
      let dx = b.x - a.x, dy = b.y - a.y;
      const min = R_B + b.r;
      const d2 = dx * dx + dy * dy;
      if (d2 >= min * min) continue;
      let d = Math.sqrt(d2);
      if (d < 1e-9) { d = 1e-9; dx = 1; dy = 0; }
      const nx = dx / d, ny = dy / d, pen = (min - d) / 2;
      a.x -= nx * pen; a.y -= ny * pen;
      b.x += nx * pen; b.y += ny * pen;
      fixed = true;
    }
  }
  return !fixed; // true = já estava tudo dentro dos limites
}

